export type NeighborhoodCenter = {
  name: string;
  lat: number;
  lng: number;
  // Rough estimate of how many restaurants that real neighborhood actually
  // has, from general knowledge of San Diego's dining scene — not pulled from
  // a live source, so treat these as ballpark relative figures, not counts.
  estimatedRestaurantCount: number;
};

// Approximate centroid per major neighborhood, used to draw map zones so every
// part of the city falls in one — independent of which neighborhoods happen to
// have a restaurant right now. Small/minor areas aren't tracked separately, so
// they fall into whichever of these zones is geographically nearest.
